with with_gaps as (select *, case when txn_time - lag(txn_time) over (partition by account_id order by txn_time asc, id asc) > interval 7 days then 1 else 0 end as session_start_flag from transactions), sessions_transactions as (select *, sum(session_start_flag) over (partition by account_id order by txn_time asc, id asc rows between unbounded preceding and current row) as island_id from with_gaps) select date_trunc('year', txn_time) as year_start, count(distinct merchant) as distinct_merchants, sum(case when txn_type = 'FEE' then island_id else 0 end) as fee_island_id, round(avg(amount), 2) as avg_amount, (unix_timestamp(max(txn_time)) - unix_timestamp(min(txn_time))) / 60 as duration_min, count(*) filter (where merchant = 'Lazada') as lazada_rows from sessions_transactions group by year_start order by avg_amount desc nulls first
